import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`writing-clone`,heroTitle:`Clone your writing style in minutes`,heroSubtitle:`Perplexity Computer analyzes your writing, extracts your unique voice and patterns, and builds a custom style guide — automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload your writing`,inputFileAccept:`.pdf,.doc,.docx`,inputFilePrefill:`Analyze the uploaded document and perform a deep writing style extraction. 1) Identify the author's voice, tone, and personality — formal vs. casual, authoritative vs. conversational, dry vs. warm. 2) Map sentence structure patterns — average sentence length, use of fragments, paragraph rhythm, and transition style. 3) Catalog vocabulary preferences — favorite words, phrases, idioms, jargon level, and reading grade level. 4) Document rhetorical habits — how the author opens pieces, builds arguments, uses analogies, handles humor, and closes. 5) Note punctuation and formatting tendencies — em dash usage, comma style, list preferences, header patterns. 6) Build a comprehensive, reusable writing style guide that captures every dimension of this author's voice. 7) Generate three sample paragraphs on different topics written in the cloned style so the author can verify accuracy. 8) Include a 'style cheat sheet' — a one-page reference card with the top 15 rules for mimicking this voice.`,heroOverlaySteps:[`Reading your document and analyzing sentence patterns`,`Extracting voice, tone, vocabulary, and rhetorical habits`,`Building a comprehensive writing style guide`,`Style guide and sample outputs generated — ready to write`],generatingSteps:[`Analyzing the uploaded file for voice, tone, structure, and vocabulary patterns`,`Designing an agent to map rhetorical habits, pacing, and stylistic fingerprints`,`Building a reusable style guide with rules, examples, and a cheat sheet`,`Setting up sample paragraph generation to verify style accuracy`],featureSectionTitle:`From writing sample to style clone`,featureCardTitles:[`Connects to your writing stack`,`Outputs you can write with`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Docs, Notion, Google Drive, Slack — Computer saves your style guide and generates on-voice drafts directly in the tools you already write in.`,`Comprehensive style guide. Voice and tone ruleset. Vocabulary map. Sentence pattern analysis. Sample paragraphs in your cloned voice. One-page cheat sheet.`],capabilitySectionTitle:`Your writing voice, on autopilot`,capabilitySectionSubtitle:`Upload a sample, step away, get back a complete style clone.`,capabilityCards:[{title:`Voice Extraction`,description:`Computer can analyze your writing for tone, personality, formality, and emotional register — distilling what makes your voice uniquely yours.`},{title:`Pattern Mapping`,description:`Computer can catalog your sentence structures, paragraph rhythms, transition habits, and punctuation tendencies into concrete, reusable rules.`},{title:`Style Verification`,description:`Computer can generate sample paragraphs on new topics in your cloned voice — so you can test accuracy before using it.`},{title:`Connect Your Tools`,description:`Computer can push your style guide to Google Docs, Notion, Google Drive, and Slack — keeping your voice accessible across every workspace.`},{title:`Refine Over Time`,description:`Computer can remember your feedback and past uploads across sessions — sharpening your style clone with every interaction.`},{title:`Drift Detection`,description:`Computer can monitor new drafts against your style guide and flag when writing drifts off-voice — before it ships.`}]});export{t as default};
